 document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 ({team:renderMarketingTeam,overview:renderOverview,agents:renderAgents,accounts:renderAccounts,content:renderContent,trends:renderTrends,runs:renderRuns,learning:renderLearning,campaigns:renderCampaignDesk,meta:renderMetaAds,settings:renderSettings}[view])();
