function renderOverview(){const p=product(),ps=forProduct(posts),rs=forProduct(runs),connections=Object.values(p.accounts).filter(a=>a.connected).length;
 $('view').innerHTML=`<p class="lead">A content team built around ${esc(p.name)}. Research becomes a brief, a brief becomes content, and measured results shape the next idea.</p><div class="summary-strip"><div><strong>${agents().length}</strong><span>editable agent roles</span></div><div><strong>${ps.filter(x=>x.status==='draft').length}</strong><span>drafts to review</span></div><div><strong>${connections} / ${Object.keys(p.accounts).length}</strong><span>verified connections</span></div><div><strong>${rs.filter(r=>r.status==='completed').length}</strong><span>completed runs</span></div></div><div class="split"><div><h2>Start with the launch</h2>${[['accounts','Create the product’s accounts','Profile copy, suggested handles, setup checklists and connection status.'],['agents','Meet the Chief of Content','Weekly creator growth, trend lifecycle, brand fit and a shot-by-shot filming brief.'],['content','Review the first content','Platform-specific captions, scripts and visual briefs. Media still needs production.']].map(([v,t,d])=>`<div class="list-row row"><div><h3>${t}</h3><p>${d}</p></div><button data-go="${v}">Open</button></div>`).join('')}<div class="actions"><button data-workflow="accounts">Generate account launch kit</button><button data-workflow="launch">Run full launch workflow</button></div></div><div><h2>What needs your attention</h2><p>${connections?'Finish verifying the remaining channels.':'The brand accounts have not been created or connected yet.'} The system can prepare their copy and content now.</p><p>There is no imported live trend feed or performance history yet. The Chief of Content uses supplied evidence and labels evergreen ideas separately.</p><div class="callout"><h3>How work moves</h3><p>Research → Chief of Content → Calendar → Writers and production → Fact checker → Skeptic → Your review → Posting → Analytics → Memory</p></div><p class="meta">The existing ten-repository registry, JEV routing, deterministic hooks, skeptic and vault remain available in Installed tools and hooks.</p></div></div><div class="section"><h2>Recent work</h2>${rs.slice(0,3).map(r=>`<div class="list-row row"><div>${esc(r.workflow)}, ${date(r.createdAt)}<p class="meta">${esc(r.job)}</p></div>${tag(r.status)}</div>`).join('')||'<p>No agent runs yet. Generate an account launch kit or a content batch to start.</p>'}</div>`;
}
function renderAgents(){
 const a=agent(selectedAgent)||agents()[0];selectedAgent=a.id;const incoming=a.dependsOn,outgoing=agents().filter(x=>x.dependsOn.includes(a.id)).map(x=>x.id),neighbors=new Set([a.id,...incoming,...outgoing]);
 const visible=allMap?agents():agents().filter(n=>neighbors.has(n.id));
 const groups=[...new Set(visible.map(n=>n.group))].map(g=>[g]);
 $('view').innerHTML=`<p>Click an agent to inspect its instructions, inputs and downstream connections. Changes apply to future runs. Each run keeps a copy of the instructions it used.</p><div class="actions"><button data-toggle-map="yes">${allMap?'Focus on selected agent':'Show all agents'}</button><button data-action="newAgent">Add an agent</button><button data-action="exportConfig">Download agent catalog</button></div><div class="graph-layout"><div class="graph-wrap"><div class="graph" id="graph"><svg id="edges" aria-hidden="true"></svg><div class="graph-groups">${groups.map(gs=>`<div class="graph-col"><h3>${esc(gs.join(' + '))}</h3>${visible.filter(a=>gs.includes(a.group)).map(n=>`<button class="node ${n.id===a.id?'selected':neighbors.has(n.id)?'':'dim'}" data-agent="${esc(n.id)}" id="node-${esc(n.id)}">${esc(n.name)}<small>v${n.version}, ${esc(n.model.replace('claude-',''))}</small></button>`).join('')}</div>`).join('')}</div></div></div><aside class="agent-detail"><span class="meta">${esc(a.group)}, v${a.version}</span><h2>${esc(a.name)}</h2><p><code>${esc(a.id)}</code></p><div class="actions"><button data-action="editAgent">Edit instructions</button><button data-action="runAgent">Run agent</button><button data-action="continueAgent">Copy coding brief</button></div><p><strong>Receives from</strong><br>${incoming.map(i=>esc(agent(i)?.name||i)).join(', ')||'Operator job and product context'}</p><p><strong>Feeds into</strong><br>${outgoing.map(i=>esc(agent(i)?.name||i)).join(', ')||'Chief of Staff and product memory'}</p><p><strong>Shared product inputs</strong><br>Brand, voice, sources, metrics, feedback and completed upstream outputs.</p><div class="prompt">${esc(a.prompt)}</div><p class="meta">Source file: <code>${esc(a.file)}</code><br>Runtime: <code>runtime/harness.py</code><br>Canonical catalog: <code>config/catalog.json</code></p><p class="meta">Dashboard edits are stored in Firebase. Future agents read them at run start; the local catalog is the install seed.</p></aside></div>`;
 requestAnimationFrame(()=>{const graph=$('graph');if(!graph)return;const b=graph.getBoundingClientRect(),paths=[];for(const n of agents())for(const dep of n.dependsOn){const x=$('node-'+dep),y=$('node-'+n.id);if(!x||!y)continue;const r=x.getBoundingClientRect(),s=y.getBoundingClientRect(),x1=r.right-b.left,y1=r.top+r.height/2-b.top,x2=s.left-b.left,y2=s.top+s.height/2-b.top,strong=n.id===a.id||dep===a.id;paths.push(`<path d="M ${x1} ${y1} C ${x1+24} ${y1},${x2-24} ${y2},${x2} ${y2}" fill="none" stroke="${strong?'var(--color-blue)':'var(--color-muted)'}" stroke-width="${strong?1.5:.6}" opacity="${strong?1:.35}" marker-end="url(#arrow)"/>`);} $('edges').innerHTML='<defs><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0,0 L5,2.5 L0,5" fill="var(--color-blue)"/></marker></defs>'+paths.join('');});
}
function renderAccounts(){const p=product();$('view').innerHTML=`<p class="lead">The same launch checklist, for every product.</p><p>Suggested handles are unverified. Create or claim each account, then record its profile. Passwords, verification codes and API tokens stay out of this dashboard. Legal acceptance and identity verification happen in the platform’s own signup flow.</p><div class="actions"><button data-workflow="accounts">Generate profile and launch kit</button><button data-action="downloadProfiles">Download profile pack</button></div>${Object.entries(p.accounts).map(([k,a])=>`<article class="account"><div class="row"><div><h2>${esc(k)}</h2><p class="meta">${esc(a.type)}</p></div>${tag(a.status,a.connected)}</div><div class="field-pair"><div><p>Suggested handles: <strong>${(a.handleCandidates||[a.handle]).map(h=>'@'+esc(h)).join(' / ')}</strong><br><small>${esc(a.availability)}</small></p><div class="bio-block"><p class="meta">Profile copy</p><p class="bio">${esc(a.bio)}</p></div><p class="meta">Website: <a href="${safeURL(a.website)}" target="_blank" rel="noopener">${esc(a.website)}</a></p><div class="actions"><a href="${safeURL(a.createUrl)}" target="_blank" rel="noopener">Open account setup</a><button data-copy-bio="${k}">Copy bio</button><button data-edit-account="${k}">Record account</button></div></div><div><ul class="checklist">${a.needs.map((step,i)=>`<li><label><input type="checkbox" data-step="${k}:${i}" ${a.stepsDone.includes(i)?'checked':''}>${esc(step)}</label></li>`).join('')}</ul><p class="meta">${a.url?`Profile: <a href="${safeURL(a.url)}" target="_blank" rel="noopener">${esc(a.url)}</a>`:'No profile recorded yet.'}<br>Posting method: ${esc(a.adapter||'manual')}<br>${a.connected?'Connection verified by runtime.':'API connection has not been verified.'}</p></div></div></article>`).join('')}`;}
function renderContent(){const ps=forProduct(posts).filter(p=>filter==='all'||p.status===filter).sort((a,b)=>(a.proposedDate||a.createdAt).localeCompare(b.proposedDate||b.createdAt));$('view').innerHTML=`<div class="row wrap"><p>Short video flow: producer → TikTok, Reels and Shorts creators → fact checker → skeptic → your review. Review the words, film the script, then attach the finished asset. Proposed dates are planning slots until a post is explicitly scheduled.</p><div class="actions"><button data-workflow="content">Generate batch</button><button data-workflow="short-video">Create TikTok, Reels and Shorts</button><button data-action="newPost">Write a post</button><button data-action="downloadPosts">Download posting CSV</button></div></div><div class="tabs">${['all','draft','approved','scheduled','needs_attention','published','rejected'].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t} (${forProduct(posts).filter(p=>t==='all'||p.status===t).length})</button>`).join('')}</div>${ps.map(p=>`<article class="post"><div class="row"><div><span class="meta">${esc(p.platform)}, ${esc(p.format)}, revision ${p.revision}</span><h3>${esc(p.title)}</h3></div>${tag(p.status,p.status==='approved')}</div><p class="proposed">${p.scheduledAt?'Scheduled '+date(p.scheduledAt):'Proposed: '+esc(p.proposedDate||'Select after review')}, ${esc(p.pillar||'Product education')}</p><p class="caption">${esc(p.caption)}</p>${p.script?`<details><summary>Phone filming script</summary><pre>${esc(p.script)}</pre></details>`:''}${p.visualBrief?`<details><summary>Visual and production brief</summary><pre>${esc(p.visualBrief)}</pre></details>`:''}<p class="meta">${esc(p.review||'Needs human claim and media review')}${p.publishError?`<br>Publication stopped: ${esc(p.publishError)}`:''}${p.mediaUrl?`<br>Media: <a href="${safeURL(p.mediaUrl)}" target="_blank" rel="noopener">Open asset</a>`:''}${p.publishedId?`<br>Publication receipt: ${esc(p.publishedId)}`:''}</p><div class="actions"><button data-edit-post="${esc(p.id)}" ${['published','publishing'].includes(p.status)?'disabled':''}>Edit draft</button><button data-approve-post="${esc(p.id)}" ${['published','approved','scheduled','publishing'].includes(p.status)?'disabled':''}>Approve this revision</button><button data-schedule-post="${esc(p.id)}" ${p.status!=='approved'?'disabled':''}>Schedule API post</button><button data-copy-post="${esc(p.id)}">Copy caption</button><button data-manual-post="${esc(p.id)}">Posting instructions</button><button data-reject-post="${esc(p.id)}" ${['published','publishing'].includes(p.status)?'disabled':''}>Reject</button></div></article>`).join('')||'<div class="empty"><h2>No posts in this view</h2><p>Generate a content batch or write a post. Drafts are private until you post them.</p></div>'}`;}
function renderTrends(){const ts=product().trendEvidence||[];$('view').innerHTML=`<p class="lead">A trend is a repeatable format, not just a popular topic or sound.</p><p>The Chief of Content compares creator counts, checks brand fit and writes exactly what to film. No connected Virlo account is available yet. Import a provider export or record evidence below; current trend reports remain evidence-limited until then.</p><div class="actions"><button data-action="newTrend">Add trend evidence</button><button data-action="importTrends">Import trend JSON</button><button data-workflow="trends">Run weekly trend brief</button><a href="https://virlo.ai/" target="_blank" rel="noopener">Open Virlo</a></div><div class="table-wrap"><table><thead><tr><th>Format and source</th><th>Creators this / last week</th><th>Change</th><th>Stage</th><th>Observed</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${esc(t.name)}<br><a href="${safeURL(t.source)}" target="_blank" rel="noopener">Source</a><p class="meta">${esc(t.keepSame||'Recipe not recorded')}</p></td><td>${esc(t.creatorsThisWeek??'Unknown')} / ${esc(t.creatorsLastWeek??'Unknown')}</td><td>${t.creatorsLastWeek>0?((t.creatorsThisWeek-t.creatorsLastWeek)/t.creatorsLastWeek*100).toFixed(0)+'%':'Not comparable'}</td><td>${esc(t.stage||'Heuristic at run time')}<br><small>${t.stage?'Provider or operator supplied':'Local rule; not Virlo classification'}</small></td><td>${esc(t.observedAt)}</td></tr>`).join('')||'<tr><td colspan="5">No measured trends imported. No stages or creator counts have been invented.</td></tr>'}</tbody></table></div><div class="section"><h2>The filming brief contract</h2><p>Every recommendation includes a source and observation date, creator velocity, lifecycle stage and confidence, early or late timing, why it fits, what to keep and what to change, opening shot, on-screen text, each beat, caption, production effort, brand safety and commercial sound rights.</p><p class="meta">Fresh → Rising → Peaking → Fading → Archived. Provider labels are retained. A count-only local heuristic is always labelled as such.</p></div>`;}
function renderRuns(){const rs=forProduct(runs),cs=forProduct(commands).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('view').innerHTML=`<p>Each run preserves its instructions, dependencies, outputs, status and reported cost. Model reports are advisory; completion does not approve media or verify live sources. Failed branches stop; completed work remains available. A deliberate resume permits at most one additional attempt per task.</p><div class="actions">${Object.keys(config.workflows).map(k=>`<button data-workflow="${k}">${esc(k)} workflow</button>`).join('')}</div>${cs.slice(0,3).map(c=>`<div class="list-row row"><div>${esc(c.action)}, ${esc(c.workflow||c.agentId||'posting pack')}<p class="meta">${esc(c.error||c.localPath||date(c.createdAt))}</p></div>${tag(c.status)}</div>`).join('')}<div class="section">${rs.map(r=>`<details class="run" ${r.status==='running'?'open':''}><summary><span>${esc(r.workflow)}, ${date(r.createdAt)}<br><small>${esc(r.job)}</small></span><span>${tag(r.status)}<br><small>$${Number(r.costUsd||0).toFixed(4)}</small></span></summary><p class="meta">Run ID: ${esc(r.id)}, Budget cap $${Number(r.maxRunUsd||12).toFixed(2)}, ${r.tasks.filter(t=>t.status==='done').length} / ${r.tasks.length} tasks completed</p>${r.status==='needs_attention'?`<button data-resume="${esc(r.id)}">Resume eligible failed tasks once</button>`:''}${r.tasks.map(t=>`<details class="task"><summary>${esc(t.contract?.name||t.id)}, ${esc(t.status)}, v${t.agentVersion} ${t.costUsd?', $'+Number(t.costUsd).toFixed(4):''}</summary><p class="meta">Receives: ${esc(t.dependsOn.join(', ')||'Product context')}, Attempts: ${t.attempts}</p>${t.error?`<p class="error">${esc(t.error)}</p>`:''}${t.output?`<p><strong>${esc(t.output.summary)}</strong></p><div class="report">${esc(t.output.body)}</div>${t.output.shortVideoPlan?renderVideoPlan(r.videoProductionPlan||t.output.shortVideoPlan,r.id):''}${(t.output.blockers||[]).map(b=>`<p class="meta">Needs attention: ${esc(b)}</p>`).join('')}`:''}</details>`).join('')}</details>`).join('')||'<div class="empty"><h2>No runs yet</h2><p>Select a workflow above. The local worker processes the queue while this Mac is awake.</p></div>'}</div>`;}
function renderLearning(){const p=product(),ms=p.metrics||[],feedback=p.feedback||[];$('view').innerHTML=`<p class="lead">Measure product growth, then improve the next batch.</p><p>Reach is useful context. Qualified site visits, free check-ins and paid conversion tell us whether the content is helping the business.</p><div class="actions"><button data-action="importMetrics">Import metrics</button><button data-workflow="review">Analyze results and plan an experiment</button><button data-action="feedback">Save editorial feedback</button></div><div class="table-wrap"><table><thead><tr><th>Post / channel</th><th>Date</th><th>Impressions</th><th>Saves</th><th>Clicks</th><th>Free check-ins</th><th>Paid conversions</th></tr></thead><tbody>${ms.map(m=>`<tr>${[m.postId||m.platform,m.date,m.impressions,m.saves,m.clicks,m.freeCheckins,m.paidConversions].map(v=>`<td>${esc(v??'Unknown')}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">No performance data imported. Unknown values remain unknown, never zero.</td></tr>'}</tbody></table></div><div class="section"><h2>Editorial memory</h2>${feedback.map(f=>`<div class="list-row"><p>${esc(f.note)}</p><small>${date(f.createdAt)}</small></div>`).join('')||'<p>Save what sounds right, what sounds wrong and why. Every future agent run receives this product’s feedback.</p>'}</div><div class="section"><h2>Persistent evidence</h2><p>Each run is saved in Firebase and mirrored locally under <code>products/${esc(productId)}/runs/</code>. Retained results and costs are filed in <code>products/${esc(productId)}/vault/</code>. Other products do not receive this memory.</p></div>`;}
function renderSettings(){const p=product();$('view').innerHTML=`<div class="row"><p class="lead">${esc(p.positioning)}</p><button data-action="editBrand">Edit brand</button></div><div class="split"><div><h2>Who we are helping</h2><p>${esc(p.audience)}</p><h2>Voice</h2><p>${esc(p.voice)}</p><h2>Content pillars</h2>${p.pillars.map(v=>`<div class="list-row">${esc(v)}</div>`).join('')}<div class="section"><h2>Claim register</h2>${p.facts.map(f=>`<div class="list-row"><p>${esc(f.claim)}</p><a href="${safeURL(f.source)}" target="_blank" rel="noopener">Product source</a><p class="meta">${esc(f.status)}</p></div>`).join('')||'<p>No verified claims yet. Add source material before using numerical claims.</p>'}<button data-action="addSource">Save source or competitor</button></div></div><div><h2>Built from your sources</h2><div class="sources">${config.sources.map(s=>`<a href="${safeURL(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><p class="meta">${esc(s.use)}</p>`).join('')}</div>${renderHarnessFrameworks()}<div class="section"><h2>Run boundaries</h2><p>Sonnet 4.6. One active content task at a time. $0.75 maximum per agent call and $12 per workflow. Retries require a deliberate resume. No publishing or email tools are exposed to content agents.</p><p>Account setup, rendered media, Virlo access and social API connections are tracked separately from generated text. The queue worker runs on this Mac.</p></div></div></div>`;}
async function queue(action,data={}){const id=uid();await put('growthCommands/'+id,{id,action,productId,status:'queued',createdAt:now(),...data});notice('Queued. The local worker will pick this up while the Mac is awake.');view='runs';location.hash=view;render();}
function runDialog(workflow,agentId){const title=agentId?'Run '+agent(agentId).name:'Run '+workflow+' workflow';openEditor(title,`<p>Product: <strong>${esc(product().name)}</strong>. Uses Sonnet 4.6 and this product’s saved context. ${agentId?'One agent call, capped at $0.75.':'Workflow cap: $12. Only selected roles are loaded.'}</p>${area('Job to complete','runJob',agentId?'Produce the next useful deliverable for this role, grounded in this product context.':workflow==='marketing-plan'?'Create a prioritized Serasona marketing plan across the ten departments. Read the current product brief, saved evidence and existing work. Route each priority to exact backing agent IDs, state missing inputs and measurable outcomes, recommend one bounded department workflow next. Do not run all roles, invent metrics or imply any execution.':workflow.startsWith('department-')?'Complete the selected department’s five specialist deliverables for this product. Use saved evidence and prior outputs. Clearly label hypotheses and missing data. Return concrete drafts or audit findings rather than empty templates. No sending, publishing, account changes or claims of live research.':workflow==='short-video'?'Create one to three complete 30 to 60 second vertical video concepts for TikTok, Instagram Reels and YouTube Shorts. Give each three opening hooks, one chosen hook, a contiguous timed master, real filming or screen-recording shots and an asset checklist. Adapt captions per platform. Use supplied evidence only; label evergreen hypotheses. No avatars or synthetic testimonials. No publication implied.':workflow==='meta-ads'?'Build the Meta ad research, original creative test matrix, campaign setup and management plan using Stacy’s post. Use the current product metaAds settings. Identify all missing account, budget, LTV, tracking and finished-asset inputs; never invent them or imply launch. Create 2 original concepts with three hooks and two bodies per concept. Keep reports concise. No live spend or activation.':workflow==='accounts'?'Prepare complete brand account launch kits for Instagram, LinkedIn, TikTok, X and YouTube. State what the operator must do to complete signup and API connection.':workflow==='trends'?'Rank supplied trends and write the strongest phone filming brief. If live evidence is missing, state it and offer clearly labelled evergreen alternatives.':'Create a practical 14-day content batch. Produce platform-specific drafts, filming scripts and visual briefs using only supported product claims.')}`,async()=>queue('run',{workflow,agentId:agentId||null,job:$('runJob').value.trim()}),'Queue run');}
function validateGraph(list){const by=new Map(list.map(a=>[a.id,a])),seen=new Set(),active=new Set();if(by.size!==list.length)throw Error('Duplicate agent ID.');function visit(id){if(active.has(id))throw Error('Dependencies would create a cycle.');if(seen.has(id))return;active.add(id);for(const d of by.get(id).dependsOn){if(!by.has(d))throw Error('Unknown dependency: '+d);visit(d);}active.delete(id);seen.add(id);}for(const id of by.keys())visit(id);}
function editAgent(isNew=false){const a=isNew?{id:'',name:'',group:'Create',dependsOn:[],prompt:'',version:0}:agent(selectedAgent);openEditor(isNew?'Add an agent':'Edit '+a.name,`${isNew?field('Agent ID','agentId'):''}${field('Agent name','agentName',a.name)}<label>Department<select id="agentGroup">${['Direct','Launch','Research','Create','Paid','Review','Publish','Learn','Grow'].map(g=>`<option ${g===a.group?'selected':''}>${g}</option>`).join('')}</select></label>${field('Dependencies, comma-separated agent IDs','agentDeps',a.dependsOn.join(', '),'text',false)}${area('Instructions','agentPrompt',a.prompt)}<p class="meta">Model is fixed to Sonnet 4.6. Version increments on save. Existing runs retain their original contract.</p>`,async()=>{const id=isNew?$('agentId').value.trim():a.id;if(!/^[a-z0-9][a-z0-9-]{0,63}$/.test(id))throw Error('Use a lowercase agent ID with letters, numbers and hyphens.');const deps=$('agentDeps').value.split(',').map(x=>x.trim()).filter(Boolean);await mutate('harness/growthConfig',c=>{if(isNew&&c.agents.some(x=>x.id===id))throw Error('Agent ID already exists.');const n={...a,id,name:$('agentName').value.trim(),group:$('agentGroup').value,dependsOn:deps,prompt:$('agentPrompt').value.trim(),version:(a.version||0)+1,model:'claude-sonnet-4-6',file:'agents/'+id+'.md'};c.agents=isNew?[...c.agents,n]:c.agents.map(x=>x.id===id?n:x);validateGraph(c.agents);return c;});selectedAgent=id;});}
function editAccount(k){const a=product().accounts[k];openEditor('Record '+k+' account',`${field('Handle','accountHandle',a.handle)}${field('Profile URL','accountUrl',a.url,'url')}${area('Profile bio','accountBio',a.bio)}<label>Account status<select id="accountStatus">${['not_created','created','profile_ready','awaiting_api','manual_ready'].map(x=>`<option ${x===a.status?'selected':''}>${x}</option>`).join('')}</select></label><p>Recording a profile does not grant API access. The posting pack works with manual posting. Secrets belong in the local connector configuration, never here.</p>`,async()=>{const url=new URL($('accountUrl').value).href;if(!url.startsWith('https://'))throw Error('Use an HTTPS profile URL.');await updateProduct(p=>{p.accounts[k]={...p.accounts[k],handle:$('accountHandle').value.trim().replace(/^@/,''),url,bio:$('accountBio').value.trim(),status:$('accountStatus').value};return p;});});}
function editPost(id){const p=id?posts.find(p=>p.id===id):{title:'',platform:'linkedin',format:'Text',caption:'',script:'',visualBrief:'',pillar:product().pillars[0],proposedDate:'',mediaUrl:''};openEditor(id?'Edit draft':'Write a post',`${field('Title','postTitle',p.title)}<div class="field-pair"><label>Platform<select id="postPlatform">${Object.keys(product().accounts).map(k=>`<option ${k===p.platform?'selected':''}>${k}</option>`).join('')}</select></label>${field('Format','postFormat',p.format)}</div>${area('Caption','postCaption',p.caption)}${area('Filming script, if needed','postScript',p.script,false)}${area('Visual brief, if needed','postVisual',p.visualBrief,false)}${field('Proposed date','postDate',p.proposedDate,'date',false)}${field('Finished media URL, if available','postMedia',p.mediaUrl,'url',false)}<p class="meta">Editing creates a new revision and removes prior approval. An asset URL alone does not verify media rights or technical requirements.</p>`,async()=>{const fields={title:$('postTitle').value.trim(),platform:$('postPlatform').value,format:$('postFormat').value.trim(),caption:$('postCaption').value.trim(),script:$('postScript').value.trim(),visualBrief:$('postVisual').value.trim(),proposedDate:$('postDate').value,mediaUrl:$('postMedia').value.trim(),status:'draft',review:'Needs human claim and media review',approval:null,scheduledAt:null};if(fields.mediaUrl&&!fields.mediaUrl.startsWith('https://'))throw Error('Media must use an HTTPS URL.');if(id)await mutate('growthContent/'+id,p=>{if(['published','publishing'].includes(p.status))throw Error('Publishing or published posts cannot be edited here.');return {...p,...fields,revision:p.revision+1,updatedAt:now()};});else{const id=uid();await put('growthContent/'+id,{...p,...fields,id,productId,revision:1,createdAt:now(),sourceAgent:'operator'});}});}
async function approvePost(id){const p=posts.find(p=>p.id===id);openEditor('Approve this exact revision',`<p><strong>${esc(p.title)}</strong>, ${esc(p.platform)}, revision ${p.revision}</p><p class="caption">${esc(p.caption)}</p><p>Approval records your editorial review. It does not publish. Confirm the claims, media rights and account before using the posting pack.</p><label><input id="reviewConfirmed" type="checkbox" required style="width:auto"> I reviewed the caption, claims, script and media rights for this revision.</label>`,async()=>{await mutate('growthContent/'+id,current=>{if(current.revision!==p.revision||['scheduled','publishing','published'].includes(current.status))throw Error('The draft or its publication state changed. Review it again.');return {...current,status:'approved',review:'Operator reviewed this revision',approval:{revision:current.revision,approvedAt:now(),uid:auth.currentUser.uid,caption:current.caption,mediaUrl:current.mediaUrl||''}};});},'Approve revision');}
async function revisionHash(p){const keys=['id','productId','platform','caption','script','visualBrief','mediaUrl','revision','scheduledAt','accountId'].sort(),data=Object.fromEntries(keys.map(k=>[k,p[k]??null]));const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(data)));return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');}
function schedulePost(id){const p=posts.find(p=>p.id===id),a=product().accounts[p.platform];if(p.mediaType==='CAROUSEL')throw Error('Download the campaign PNGs and use native manual posting. Carousel API upload is not connected; this post will not be reduced to text.');if(!a.connected||a.adapter!=='native')throw Error('This account has no verified API connection. Use Posting instructions for native manual posting.');if(!['linkedin','instagram','x'].includes(p.platform))throw Error('This platform currently uses the manual posting pack.');openEditor('Schedule exact post and destination',`<p><strong>${esc(p.title)}</strong>, revision ${p.revision}</p><p>Destination: ${esc(p.platform)}, ${esc(a.connectionLabel||a.accountId)}, account ${esc(a.accountId)}</p><p class="caption">${esc(p.caption)}</p><p>Media URL: ${esc(p.mediaUrl||'None; text-only post')}</p>${field('Publish date and time, in this browser’s local timezone','publishTime','','datetime-local')}<p class="meta">Browser timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. The Mac must be awake and online at the scheduled time. This approves this caption, asset URL, revision, account and time for publication.</p><label><input type="checkbox" id="scheduleReviewed" required style="width:auto"> Publish this exact revision to this account at the selected time.</label>`,async()=>{const scheduledAt=new Date($('publishTime').value).toISOString();if(new Date(scheduledAt).getTime()<Date.now()+60000)throw Error('Choose a time at least one minute in the future.');const proposed={...p,scheduledAt,accountId:a.accountId};const hash=await revisionHash(proposed);await mutate('growthContent/'+id,c=>{if(c.revision!==p.revision||c.status!=='approved')throw Error('The draft changed. Review it again.');return {...c,status:'scheduled',scheduledAt,accountId:a.accountId,approval:{...c.approval,hash,scheduledAt,accountId:a.accountId,uid:auth.currentUser.uid}};});},'Schedule publication');}
function postingInstructions(id){const p=posts.find(p=>p.id===id),a=product().accounts[p.platform];openEditor('Post on '+p.platform,`<p>${esc(p.title)}, ${tag(p.status)}</p><p>${p.status==='approved'?'This revision is approved for manual posting.':'Review and approve the draft before posting.'}</p><p class="caption">${esc(p.caption)}</p><p>${['instagram','tiktok','youtube'].includes(p.platform)?'Film or render the asset from the script and brief. Upload the finished media in the native app. Confirm licensed sound, disclosure and cover.':'Paste the caption in the platform’s native composer. Attach media only after review.'}</p><p><a href="${safeURL(a.url||a.profileUrl)}" target="_blank" rel="noopener">Open ${esc(p.platform)}</a></p>${field('Published post URL or platform receipt','receipt','','url')}<p class="meta">Use Record publication only after the platform visibly confirms the post is live. API publishing is unavailable until an account connection is verified.</p>`,async()=>{if(p.status!=='approved')throw Error('Approve this revision before recording a publication.');const url=new URL($('receipt').value).href;if(!url.startsWith('https://'))throw Error('Use the published HTTPS post URL.');await mutate('growthContent/'+id,c=>{if(c.revision!==p.revision||c.status!=='approved')throw Error('The draft changed. Review it again.');return {...c,status:'published',publishedId:url,publishedAt:now(),deliveryMethod:'operator_recorded'};});},'Record publication');}
function download(name,text,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadPosts(){const cell=x=>'"'+String(x??'').replaceAll('"','""')+'"';const columns=['id','platform','status','title','caption','script','visualBrief','proposedDate','mediaUrl'];download(productId+'-posting-pack.csv',[columns.join(','),...forProduct(posts).map(p=>columns.map(k=>cell(p[k])).join(','))].join('\r\n'),'text/csv');notice('Posting CSV downloaded through your browser.');}
function newTrend(){openEditor('Add trend evidence',`${field('Trend format name','trendName')}${field('Source URL','trendSource','','url')}<div class="field-pair">${field('Creators this week','trendThis',0,'number')}${field('Creators last week','trendLast',0,'number')}</div>${field('Observation date','trendDate',now().slice(0,10),'date')}<label>Provider lifecycle label<select id="trendStage"><option value="">Not supplied; label local heuristic</option>${['Fresh','Rising','Peaking','Fading','Archived'].map(s=>`<option>${s}</option>`).join('')}</select></label>${area('What makes the format repeatable','trendRecipe')}`,async()=>{const a=Number($('trendThis').value),b=Number($('trendLast').value);if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<0)throw Error('Creator counts must be nonnegative integers.');const source=$('trendSource').value;if(!source.startsWith('https://'))throw Error('Use an HTTPS source URL.');await updateProduct(p=>{p.trendEvidence=[...(p.trendEvidence||[]),{id:uid(),name:$('trendName').value.trim(),source,creatorsThisWeek:a,creatorsLastWeek:b,observedAt:$('trendDate').value,stage:$('trendStage').value||null,keepSame:$('trendRecipe').value.trim(),commercialSoundRights:'Needs verification'}];return p;});});}
function importData(kind){const metric=kind==='metrics';openEditor(metric?'Import measured metrics':'Import trend evidence',`<p>${metric?'Paste actual exported post measurements as a JSON array. Missing measurements must be null. Required: postId or platform, date. Optional: impressions, saves, clicks, freeCheckins, paidConversions.':'Paste a JSON array. Each row needs name, source URL, observedAt date, creatorsThisWeek and creatorsLastWeek. Optional: stage and keepSame. Import only measured comparable periods.'}</p>${area('JSON data','importData','')}`,async()=>{const rows=JSON.parse($('importData').value);if(!Array.isArray(rows)||rows.length>500)throw Error('Use an array of at most 500 rows.');for(const r of rows){if(metric){if(!(r.postId||r.platform)||!r.date)throw Error('Each metric needs postId or platform and date.');for(const k of ['impressions','saves','clicks','freeCheckins','paidConversions'])if(r[k]!=null&&(!Number.isFinite(r[k])||r[k]<0))throw Error('Metrics must be nonnegative numbers or null.');}else if(!r.name||!r.source?.startsWith('https://')||!r.observedAt||!Number.isInteger(r.creatorsThisWeek)||!Number.isInteger(r.creatorsLastWeek)||Math.min(r.creatorsThisWeek,r.creatorsLastWeek)<0)throw Error('Each trend needs a name, HTTPS source, observedAt and nonnegative integer creator counts.');}await updateProduct(p=>{p[kind]=[...(p[kind]||[]),...rows];return p;});});}
function editBrand(){const p=product();openEditor('Edit product brand',`${field('Product name','brandName',p.name)}${field('Website','brandWebsite',p.website,'url')}${area('Positioning','brandPosition',p.positioning)}${area('Audience','brandAudience',p.audience)}${area('Voice','brandVoice',p.voice)}${area('Content pillars, one per line','brandPillars',p.pillars.join('\n'))}${area('Forbidden claims or content, one per line','brandForbidden',p.forbidden.join('\n'),false)}`,async()=>updateProduct(p=>({...p,name:$('brandName').value.trim(),website:$('brandWebsite').value.trim(),positioning:$('brandPosition').value.trim(),audience:$('brandAudience').value.trim(),voice:$('brandVoice').value.trim(),pillars:$('brandPillars').value.split('\n').map(x=>x.trim()).filter(Boolean),forbidden:$('brandForbidden').value.split('\n').map(x=>x.trim()).filter(Boolean)})));}
$('view').onclick=async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(b.dataset.toggleMap){allMap=!allMap;render();} if(b.dataset.teamAgent){selectedAgent=b.dataset.teamAgent;allMap=false;view='agents';location.hash=view;render();} if(b.dataset.videoPlan){const r=runs.find(r=>r.id===b.dataset.videoPlan);const plan=r.videoProductionPlan||r.tasks.find(t=>t.output?.shortVideoPlan)?.output.shortVideoPlan;download(productId+'-filming-plan.json',JSON.stringify({status:'needs_footage',subtitleTiming:'Estimated; align to actual recording',videos:plan},null,2));} if(b.dataset.selectCampaign){selectedCampaignId=b.dataset.selectCampaign;render();} if(b.dataset.campaignAgent){selectedAgent=b.dataset.campaignAgent;view='agents';location.hash=view;render();} if(b.dataset.askHook)campaignRequest('hook',b.dataset.askHook); if(b.dataset.reviewCampaign)campaignRequest('review',b.dataset.reviewCampaign); if(b.dataset.editSlide){const [id,i]=b.dataset.editSlide.split(':');editCampaignSlide(id,Number(i));} if(b.dataset.lockSlide){const [id,i]=b.dataset.lockSlide.split(':');await lockCampaignSlide(id,Number(i));} if(b.dataset.downloadSlide){const [id,i]=b.dataset.downloadSlide.split(':');downloadCampaignSlide(id,Number(i));} if(b.dataset.approveCampaign)approveCampaign(b.dataset.approveCampaign); if(b.dataset.selectVariations)chooseCampaignVariations(b.dataset.selectVariations); if(b.dataset.produceVariations)await queue('campaign_produce',{campaignId:b.dataset.produceVariations}); if(b.dataset.campaignSchedule)prepareCampaignSchedule(b.dataset.campaignSchedule); if(b.dataset.campaignMetrics)campaignMetrics(b.dataset.campaignMetrics); if(b.dataset.go){view=b.dataset.go;location.hash=view;render();}
 if(b.dataset.agent){selectedAgent=b.dataset.agent;render();} if(b.dataset.metaAgent){selectedAgent=b.dataset.metaAgent;view='agents';location.hash=view;render();}
 if(b.dataset.workflow)runDialog(b.dataset.workflow);
 if(b.dataset.filter){filter=b.dataset.filter;render();}
 if(b.dataset.editAccount)editAccount(b.dataset.editAccount);
 if(b.dataset.copyBio){await navigator.clipboard.writeText(product().accounts[b.dataset.copyBio].bio);notice('Profile bio copied.');}
 if(b.dataset.editPost)editPost(b.dataset.editPost);
 if(b.dataset.approvePost)approvePost(b.dataset.approvePost);
 if(b.dataset.schedulePost)schedulePost(b.dataset.schedulePost);
 if(b.dataset.copyPost){await navigator.clipboard.writeText(posts.find(p=>p.id===b.dataset.copyPost).caption);notice('Caption copied.');}
 if(b.dataset.manualPost)postingInstructions(b.dataset.manualPost);
 if(b.dataset.rejectPost)await mutate('growthContent/'+b.dataset.rejectPost,p=>{if(['published','publishing'].includes(p.status))throw Error('Publishing or published posts cannot be rejected here.');return {...p,status:'rejected',approval:null};});
 if(b.dataset.resume)await queue('resume',{runId:b.dataset.resume});
 const actions={campaignRequest:()=>campaignRequest(),campaignReference,editMetaAds,metaEvidence,metaMetrics,metaSync,metaPerformance:()=>runDialog('agent','meta-ads-performance'),editAgent:()=>editAgent(),newAgent:()=>editAgent(true),runAgent:()=>runDialog('agent',selectedAgent),continueAgent:async()=>{const a=agent(selectedAgent);await navigator.clipboard.writeText(`Continue programming the ${a.name} agent in /Users/amitmehta/Downloads/Serasona-Growth-Harness. Read runtime/harness.py, config/catalog.json and ${a.file}. The live instruction contract is owner-only Firestore harness/growthConfig, agent ${a.id}, version ${a.version}. Inputs: ${a.dependsOn.join(', ')||'product context'}. Preserve existing product isolation, exact-revision review and no email sending. Inspect latest product ${productId} runs before changing anything. Implement and test a concrete improvement, then update its version and deployment.`);notice('Coding brief copied. Paste it into a coding chat to continue this agent.');},exportConfig:()=>download('growth-agent-catalog.json',JSON.stringify(config,null,2)),downloadProfiles:()=>download(productId+'-account-launch-kit.json',JSON.stringify(product().accounts,null,2)),downloadPosts,newPost:()=>editPost(),newTrend,importTrends:()=>importData('trendEvidence'),importMetrics:()=>importData('metrics'),editBrand,feedback:()=>openEditor('Save editorial feedback',area('What should this product’s agents remember?','feedbackNote'),async()=>updateProduct(p=>{p.feedback=[...(p.feedback||[]),{note:$('feedbackNote').value.trim(),createdAt:now()}];return p;})),addSource:()=>openEditor('Save source',`${field('Title','sourceTitle')}${field('Source URL','sourceUrl','','url')}${area('Relevant evidence or notes','sourceNote')}`,async()=>updateProduct(p=>{p.savedSources=[...(p.savedSources||[]),{title:$('sourceTitle').value.trim(),url:$('sourceUrl').value,notes:$('sourceNote').value.trim(),savedAt:now()}];return p;}))};
 if(b.dataset.action)await actions[b.dataset.action]?.();
 }catch(e){error(e);}};
$('view').onchange=async e=>{if(e.target.dataset.step){const [k,i]=e.target.dataset.step.split(':');try{await updateProduct(p=>{const set=new Set(p.accounts[k].stepsDone);e.target.checked?set.add(Number(i)):set.delete(Number(i));p.accounts[k].stepsDone=[...set];return p;});}catch(e){error(e);}}};
setInterval(()=>{if(runtime)$('worker').textContent=Date.now()-new Date(runtime.updatedAt).getTime()<120000?'Worker online, Sonnet 4.6':'Worker offline, Mac must be awake';},30000);

// Included in growth.js; uses the same authenticated product workspace and live store.
function renderMetaAds(){
 const m=product().metaAds||{},rows=m.insights||[],money=v=>v==null?'Not set':esc(m.currency||'Currency not set')+' '+Number(v).toFixed(2);
 const needs=[!m.connected&&'Verify the Meta ad account connection',!m.pageId&&'Record the Facebook Page ID',!m.dailyBudget&&'Set the total daily budget',!m.testCap&&'Set the test spend cap',!m.countries?.length&&'Choose target countries',m.trackingStatus!=='Verified eligible'&&'Verify the eligible conversion source and event'].filter(Boolean);
 $('view').innerHTML=`<p class="lead">Research the desire. Test the concept. Measure the result.</p><p>Built from <a href="https://x.com/stacy_siz/status/2112257882989191445" target="_blank" rel="noopener">Stacy’s Meta ads workflow</a>, with a reusable product brief, creative testing and measured performance feedback.</p><div class="actions"><button data-workflow="meta-ads" class="primary">Generate Meta ads launch plan</button><button data-action="editMetaAds">Campaign settings</button><button data-action="metaEvidence">Add competitor ad</button><button data-action="metaMetrics">Import ad metrics</button><button data-action="metaSync">Sync Meta Insights</button></div><div class="summary-strip"><div><strong>${m.connected?'Verified':'Not connected'}</strong><span>Meta account</span></div><div><strong>${money(m.dailyBudget)}</strong><span>total daily budget</span></div><div><strong>${money(m.testCap)}</strong><span>test spend cap</span></div><div><strong>${rows.length}</strong><span>measured ad rows</span></div></div><div class="split"><div><h2>Your paid media team</h2>${[['meta-ads-research','Research','Audience desire, 2 to 3 competitors, source links, hooks, demonstrations and CTAs.'],['meta-ads-creative','Creative','One concept per ad set. Three hooks × two bodies gives six controlled variants.'],['meta-ads-manager','Meta Ads Manager','Economics, objective, event eligibility, geography, devices, placements and launch checks.'],['meta-ads-performance','Performance','Event quality, attribution lag, CPA, ROAS when measurable, fatigue and the next test.']].map(([id,name,desc])=>`<div class="list-row row"><div><h3>${name}</h3><p>${desc}</p></div><button data-meta-agent="${id}">Open agent</button></div>`).join('')}</div><div><h2>Ready to launch?</h2>${needs.length?needs.map(n=>`<div class="list-row">${esc(n)}</div>`).join(''):'<p>Connection and settings recorded. Finished media, a complete reviewed API package and placement previews are still required.</p>'}<div class="callout"><h3>Creation and management boundary</h3><p>The native adapter supports reviewed image and video packages, creates campaigns, ad sets and ads PAUSED, imports Insights and can pause account-owned objects. Activation and live budget increases stay in Ads Manager.</p><p>Use <code>python3 runtime/connect.py --help</code> for local account connection and <code>python3 runtime/meta_ads.py --help</code> for the reviewed package workflow. Tokens never enter this dashboard.</p></div></div></div><div class="section"><h2>Economics and delivery</h2><p>Contribution LTV: ${money(m.contributionLtv)}, Target CPA: ${money(m.targetCpa)}<br>Countries: ${esc(m.countries?.join(', ')||'Not selected')}, Platforms: ${esc((m.platforms||[]).join(', ')||'Not selected')}<br>Devices: ${esc((m.devices||[]).join(', ')||'Not selected')}, Conversion event: ${esc(m.conversionEvent||'Not verified')}<br>Tracking: ${esc(m.trackingStatus||'Not verified')}</p><p class="meta">Stacy’s budget multiples and scaling percentages are hypotheses to evaluate, not automatic spend rules. Ad age and visible delivery do not prove competitor profitability. Automatic enhancements and related media need checking in every current placement preview.</p></div><div class="section"><h2>Competitor evidence</h2>${(m.competitorAds||[]).map(a=>`<div class="list-row"><a href="${safeURL(a.url)}" target="_blank" rel="noopener">${esc(a.name)}</a><p>${esc(a.notes)}</p><small>Observed ${esc(a.observedAt)}. Competitor results unknown unless independently supplied.</small></div>`).join('')||'<p>No competitor ads supplied. Research runs produce search briefs until real source ads are available.</p>'}</div><div class="section"><h2>Measured performance</h2><div class="table-wrap"><table><thead><tr><th>Ad / period</th><th>Spend</th><th>Impressions</th><th>Clicks</th><th>Conversions</th><th>Revenue</th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr>${[r.ad_name||r.name||r.ad_id||'Imported ad',r.spend,r.impressions,r.clicks,r.conversions,r.revenue].map(v=>`<td>${esc(v??'Unknown')}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="6">No measured ad performance yet. Purchase counts are never guessed from overlapping action types.</td></tr>'}</tbody></table></div><p class="meta">${esc(m.insightSnapshot?JSON.stringify(m.insightSnapshot):'Add an explicit measurement period and conversion definition with every import.')}</p><button data-action="metaPerformance">Review performance</button></div>`;
}
function editMetaAds(){const m=product().metaAds||{};openEditor('Meta campaign settings',`<p>These settings guide proposals. Saving does not create ads, activate campaigns or spend money. Current account: ${esc(m.accountId||'Not connected')}.</p><div class="field-pair">${field('Account currency','metaCurrency',m.currency||'USD')}${field('Facebook Page ID, when created','metaPage',m.pageId||'','text',false)}${field('Total daily budget, account currency','metaDaily',m.dailyBudget??'','number')}${field('Test spend cap, account currency','metaCap',m.testCap??'','number')}${field('Target CPA, if established','metaCpa',m.targetCpa??'','number',false)}${field('Contribution LTV, if established','metaLtv',m.contributionLtv??'','number',false)}</div>${field('Target countries, two-letter codes separated by commas','metaCountries',(m.countries||[]).join(', '))}<label>Device scope<select id="metaDevices"><option value="both" ${(m.devices||[]).length===2?'selected':''}>Mobile and desktop for a web destination</option><option value="mobile" ${(m.devices||[]).length===1&&m.devices[0]==='mobile'?'selected':''}>Mobile only</option><option value="desktop" ${(m.devices||[]).length===1&&m.devices[0]==='desktop'?'selected':''}>Desktop only</option></select></label><label>Conversion tracking status<select id="metaTracking">${['Not verified','Eligibility review needed','Verified eligible'].map(x=>`<option ${m.trackingStatus===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Conversion event, only after eligibility review','metaEvent',m.conversionEvent||'','text',false)}<p>Baseline placements: Facebook and Instagram. Current previews must confirm enhancements and related media are off. For this wellness product, do not send voice recordings, scores, diagnoses, symptoms or sensitive page parameters to Pixel or CAPI.</p>`,async()=>{const daily=Number($('metaDaily').value),cap=Number($('metaCap').value),currency=$('metaCurrency').value.trim().toUpperCase(),countries=$('metaCountries').value.split(',').map(v=>v.trim().toUpperCase()).filter(Boolean);if(!Number.isFinite(daily)||!Number.isFinite(cap)||daily<=0||cap<=0)throw Error('Daily budget and test cap must be positive amounts.');if(!/^[A-Z]{3}$/.test(currency)||countries.some(c=>!/^[A-Z]{2}$/.test(c))||!countries.length)throw Error('Use a three-letter currency and two-letter country codes.');if(m.connected&&currency!==m.currency)throw Error('Currency must match the verified Meta account.');const optional=id=>$(id).value===''?null:Number($(id).value);for(const id of ['metaCpa','metaLtv'])if(optional(id)!==null&&(!Number.isFinite(optional(id))||optional(id)<=0))throw Error('Established CPA and LTV must be positive, or omitted as unknown.');if($('metaTracking').value==='Verified eligible'&&!$('metaEvent').value.trim())throw Error('Record the eligible conversion event before marking tracking verified.');await updateProduct(p=>{p.metaAds={...(p.metaAds||{}),currency,pageId:$('metaPage').value.trim()||null,dailyBudget:daily,testCap:cap,targetCpa:optional('metaCpa'),contributionLtv:optional('metaLtv'),countries,devices:$('metaDevices').value==='both'?['mobile','desktop']:[$('metaDevices').value],platforms:['facebook','instagram'],trackingStatus:$('metaTracking').value,conversionEvent:$('metaEvent').value.trim()||null,settingsUpdatedAt:now()};return p;});});}
function metaEvidence(){openEditor('Add a real competitor ad',`${field('Competitor or Page name','metaCompName')}${field('Meta Ads Library ad URL','metaCompUrl','','url')}${field('Observation date','metaCompDate',now().slice(0,10),'date')}${area('Hook, product reveal, demonstration, CTA and visible evidence','metaCompNotes')}`,async()=>{const u=new URL($('metaCompUrl').value);if(u.protocol!=='https:'||!['facebook.com','www.facebook.com','transparency.meta.com'].includes(u.hostname))throw Error('Use the actual HTTPS Meta Ads Library source.');await updateProduct(p=>{p.metaAds={...(p.metaAds||{})};p.metaAds.competitorAds=[...(p.metaAds.competitorAds||[]),{id:uid(),name:$('metaCompName').value.trim(),url:u.href,observedAt:$('metaCompDate').value,notes:$('metaCompNotes').value.trim()}];return p;});});}
function metaMetrics(){openEditor('Import measured Meta ad metrics',`<p>Paste a JSON array of aggregated ad rows. Every row needs name or ad_id, date, currency and attribution. Optional numbers: spend, impressions, clicks, conversions, revenue. Unknown values stay null. Do not include personal identifiers, wellness results or user-level events.</p>${area('Aggregated metrics JSON','metaRows')}`,async()=>{const rows=JSON.parse($('metaRows').value),allowed=new Set(['name','ad_id','date','currency','attribution','spend','impressions','clicks','conversions','revenue']);if(!Array.isArray(rows)||rows.length>500)throw Error('Use at most 500 aggregate rows.');for(const r of rows){if(!(r.name||r.ad_id)||!r.date||!r.currency||!r.attribution||Object.keys(r).some(k=>!allowed.has(k)))throw Error('Use the specified aggregate fields and include date, currency and attribution.');for(const k of ['spend','impressions','clicks','conversions','revenue'])if(r[k]!=null&&(!Number.isFinite(r[k])||r[k]<0))throw Error('Metrics must be nonnegative numbers or null.');}await updateProduct(p=>{p.metaAds={...(p.metaAds||{})};p.metaAds.insights=[...(p.metaAds.insights||[]),...rows];p.metaAds.insightSnapshot={source:'Operator aggregate import',importedAt:now(),attribution:'Per-row attribution, compare like windows only'};return p;});});}
function metaSync(){if(!product().metaAds?.connected)throw Error('Connect this product’s Meta ad account locally before syncing Insights.');openEditor('Sync Meta Insights',`${field('Start date','metaSince','','date')}${field('End date','metaUntil',now().slice(0,10),'date')}<p>Reads aggregated ad performance from this product’s verified account. No campaign changes are made.</p>`,async()=>{if($('metaSince').value>$('metaUntil').value)throw Error('Start date must precede end date.');await queue('meta_sync',{since:$('metaSince').value,until:$('metaUntil').value});},'Sync Insights');}

function todayInZone(offset=0){return new Intl.DateTimeFormat('en-CA',{timeZone:product().timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(Date.now()+offset*86400000));}
function renderCampaignDesk(){
 const cs=forProduct(campaigns).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),selected=cs.find(c=>c.id===selectedCampaignId)||cs[0];if(selected)selectedCampaignId=selected.id;
 $('view').innerHTML=`<p class="lead">One conversation, from a useful reference to a finished slideshow.</p><p>This operator adapts the workflow in <a href="https://x.com/PerezHatesAI/status/2112574200707727786" target="_blank" rel="noopener">Pedro Pérez’s post</a>. It uses your product context and existing publishing workflow. Muse, WhatsApp and Postiz are not required.</p><div class="actions"><button data-action="campaignRequest" class="primary">Talk to the campaign operator</button><button data-action="campaignReference">Add a real reference</button><button data-campaign-agent="organic-campaign-operator">Open agent instructions</button></div>${renderCampaignConversation(selected)}<div class="flow-line">Reference → Hook and payoff → Your selection → Slides → Selected variations → Reviewed schedule → Measured learning</div><div class="split"><div><h2>Your campaigns</h2>${cs.map(c=>`<div class="list-row row"><div><h3>${esc(c.title)}</h3><p class="meta">${tag(c.status)} Revision ${c.revision}${c.parentId?', selected variation':''}</p></div><button data-select-campaign="${esc(c.id)}">${selected?.id===c.id?'Selected':'Open'}</button></div>`).join('')||'<p>No slideshow campaign yet. Tell the operator what you want to create. It will label an idea as an evergreen hypothesis when no verified reference is available.</p>'}</div><div><h2>How this stays useful</h2><p>Teach the product once, then use short requests. Review references and concepts before publishing. A hook-only revision preserves the other rendered slide bytes. Choose at most two variations to produce.</p><p>Schedules are proposals capped at two posts per channel per day, with spacing and family separation. They enter Content studio as private drafts. Final posting still needs a connected account or native upload.</p><p class="meta">No live reference feed is connected. Saved references and supplied metrics are evidence; the source’s million-view result is not a promise. Typography-based PNG/SVG assets are produced locally without generated photos or avatars.</p></div></div>${selected?renderCampaignDetail(selected):''}<div class="section"><h2>Reference library</h2>${(product().organicReferences||[]).map(r=>`<div class="list-row"><a href="${safeURL(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a><p>${esc(r.hook)}</p><p class="meta">${esc(r.format)}, observed ${esc(r.observedAt)}, ${esc(r.mechanism)}</p></div>`).join('')||'<p>Save real short-form references here. The operator looks for the attention and payoff mechanism, including adjacent niches, without copying the original story or claiming unverified performance.</p>'}</div>`;
}
function renderCampaignDetail(c){return `<div class="section"><div class="row wrap"><div><h2>${esc(c.title)}</h2><p>${esc(c.evidenceBasis)}</p><p class="meta">${esc(c.mechanism)}${c.referenceUrl?`, <a href="${safeURL(c.referenceUrl)}" target="_blank" rel="noopener">Reference</a>`:''}</p></div>${tag(c.status,c.status==='approved')}</div><div class="campaign-assets">${c.assets.map((a,i)=>`<article><img src="${esc(a.pngDataUrl)}" alt="Slide ${i+1}: ${esc(c.slides[i].title)}" loading="lazy"><p class="meta">${esc(c.slides[i].id)}, revision ${a.revision}, ${c.slideLocks.includes(a.slideId)?'locked':'editable'}</p><div class="actions"><button data-download-slide="${esc(c.id)}:${i}">Download PNG</button><button data-edit-slide="${esc(c.id)}:${i}">Edit this slide</button><button data-lock-slide="${esc(c.id)}:${i}">${c.slideLocks.includes(a.slideId)?'Unlock':'Lock'} slide</button></div></article>`).join('')}</div><p class="caption">${esc(c.caption)}</p><div class="actions"><button data-ask-hook="${esc(c.id)}">Ask for a hook-only revision</button><button data-approve-campaign="${esc(c.id)}" ${c.status==='approved'?'disabled':''}>Approve creative revision</button><button data-select-variations="${esc(c.id)}">Choose variations</button><button data-produce-variations="${esc(c.id)}" ${!c.selectedVariationIds.length?'disabled':''}>Produce chosen variations</button><button data-campaign-schedule="${esc(c.id)}">Prepare schedule</button><button data-campaign-metrics="${esc(c.id)}">Add performance snapshot</button><button data-review-campaign="${esc(c.id)}">Review results</button></div><details><summary>Three variation options</summary>${c.variations.map(v=>`<div class="list-row"><h3>${esc(v.title)} ${c.selectedVariationIds.includes(v.id)?tag('selected'):''}</h3><p>${esc(v.scenario)}</p><p class="meta">${esc(v.slides[0].title)}</p></div>`).join('')}</details>${c.scheduleProposals?.length?`<div class="section"><h3>Proposed schedule, not published</h3>${c.scheduleProposals.map(s=>`<p>${esc(s.title)}, ${date(s.at)}, ${esc(s.timezone)}</p>`).join('')}<a href="#content">Review final drafts in Content studio</a></div>`:''}${c.metricsSnapshots?.length?`<div class="section"><h3>Measured snapshots</h3>${c.metricsSnapshots.map(m=>`<p>${esc(m.source)}, ${m.hours.toFixed(1)} hours ${m.hours<24?', early snapshot':''}<br><small>Views ${esc(m.views??'Unknown')}, Profile visits ${esc(m.profileVisits??'Unknown')}, Clicks ${esc(m.clicks??'Unknown')}, Trials ${esc(m.trials??'Unknown')}, Paid conversions ${esc(m.paidConversions??'Unknown')}</small></p>`).join('')}</div>`:''}${c.lastReview?`<details><summary>Latest operator review</summary><div class="report">${esc(c.lastReview.body)}</div></details>`:''}`;}
function campaignRequest(mode='new',id=selectedCampaignId){const selected=campaigns.find(c=>c.id===id);openEditor(mode==='hook'?'Revise the hook only':mode==='review'?'Review campaign results':'Talk to your campaign operator',`<p>${selected?'Selected campaign: '+esc(selected.title):'No existing campaign selected. A new concept will be created.'}</p><p>${mode==='hook'?'Only the first slide can change. The payoff and other rendered assets stay unchanged. A locked hook must be unlocked first.':mode==='review'?'The operator uses actual snapshots and reports missing evidence. No assets or posts are created in review mode.':'Use a short request. Your product brief, saved references, feedback and campaign history provide the context. A new draft includes actual PNG/SVG slides and three variation options.'}</p>${area('Your request','campaignMessage',mode==='new'?'Create a two-slide organic concept for this product. Make the first slide curious and useful, and reveal the product naturally in the payoff. Use only supported facts. If no tested reference exists, label the idea as an evergreen hypothesis.':mode==='hook'?'Make the hook shorter and more natural. Leave the payoff and every other slide exactly as it is.':'Review the actual snapshots, distinguish early observations from a 24-hour result, and propose one next test. Do not invent missing metrics.')}`,async()=>{await queue('campaign_request',{mode,campaignId:selected?.id||null,request:$('campaignMessage').value.trim()});},'Send request');}
function campaignReference(){openEditor('Save a real content reference',`${field('Reference title','refTitle')}${field('Original post URL','refUrl','','url')}${field('Observation date','refDate',todayInZone(),'date')}${field('Format, such as slideshow or short video','refFormat')}${area('Opening hook and first frame or seconds','refHook')}${area('Curiosity, retention mechanism and payoff','refMechanism')}${area('Measured performance and source, or explicitly unknown','refEvidence','Performance not verified. No impression or conversion data supplied.')}`,async()=>{const url=new URL($('refUrl').value).href;if(!url.startsWith('https://'))throw Error('Use the actual HTTPS reference URL.');await updateProduct(p=>{p.organicReferences=[...(p.organicReferences||[]),{id:uid(),title:$('refTitle').value.trim(),url,observedAt:$('refDate').value,format:$('refFormat').value.trim(),hook:$('refHook').value.trim(),mechanism:$('refMechanism').value.trim(),evidence:$('refEvidence').value.trim()}];return p;});});}
function editCampaignSlide(id,index){const c=campaigns.find(c=>c.id===id),s=c.slides[index];if(c.slideLocks.includes(s.id))throw Error('Unlock this slide explicitly before editing it.');openEditor('Edit only '+s.id,`${field('Top label','slideLabel',s.label)}${field('Headline','slideTitle',s.title)}${area('Body text','slideText',s.text)}${field('Footer','slideFooter',s.footer)}<p>Only this slide is rendered again. Other asset hashes remain unchanged. The campaign returns to draft for a fresh review.</p>`,async()=>queue('campaign_patch',{campaignId:id,slideId:s.id,fields:{label:$('slideLabel').value.trim(),title:$('slideTitle').value.trim(),text:$('slideText').value.trim(),footer:$('slideFooter').value.trim()}}),'Render this slide');}
async function lockCampaignSlide(id,index){await mutate('growthCampaigns/'+id,c=>{const locks=new Set(c.slideLocks);const sid=c.slides[index].id;locks.has(sid)?locks.delete(sid):locks.add(sid);c.slideLocks=[...locks];return c;});}
async function campaignHash(c){const value=[c.revision,c.caption,c.slides.map((s,i)=>[s.id,s.label,s.title,s.text,s.footer,c.assets[i].sha256])];const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(value)));return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('');}
function approveCampaign(id){const c=campaigns.find(c=>c.id===id);openEditor('Approve this creative revision',`<p>${esc(c.title)}, revision ${c.revision}</p><p>${esc(c.caption)}</p><p>Review both the actual artwork and caption, including claims and rights. This approval permits schedule preparation. It does not publish.</p><label><input type="checkbox" required style="width:auto"> I reviewed the artwork, caption and product claims for this revision.</label>`,async()=>{const hash=await campaignHash(c);await mutate('growthCampaigns/'+id,current=>{if(current.revision!==c.revision)throw Error('The creative changed. Review the new revision.');return {...current,status:'approved',approval:{revision:current.revision,hash,uid:auth.currentUser.uid,approvedAt:now()}};});},'Approve creative');}
function chooseCampaignVariations(id){const c=campaigns.find(c=>c.id===id);openEditor('Choose at most two variations',c.variations.map(v=>`<label><input type="checkbox" class="variationChoice" value="${esc(v.id)}" ${c.selectedVariationIds.includes(v.id)?'checked':''} style="width:auto"> ${esc(v.title)}</label><p class="meta">${esc(v.scenario)}</p>`).join(''),async()=>{const ids=[...$('editorBody').querySelectorAll('.variationChoice:checked')].map(x=>x.value);if(ids.length>2)throw Error('Select at most two. The others remain concepts.');await mutate('growthCampaigns/'+id,c=>({...c,selectedVariationIds:ids}));});}
function prepareCampaignSchedule(id){const cs=forProduct(campaigns).filter(c=>c.status==='approved');openEditor('Prepare a reviewed schedule',`<p>Choose approved revisions. Maximum two posts per channel per day. Local planning slots are 09:00 and 17:00 with a minimum four-hour gap. Same-family variations are separated by another family or at least 24 hours. Existing scheduled/published posts are considered. Final posts remain drafts for your review.</p>${cs.map(c=>`<label><input type="checkbox" class="scheduleChoice" value="${esc(c.id)}" ${c.id===id?'checked':''} style="width:auto"> ${esc(c.title)}</label>`).join('')||'<p>No approved creative revisions yet.</p>'}${field('First proposed date','campaignStart',todayInZone(1),'date')}<label>Channel<select id="campaignPlatform">${Object.keys(product().accounts).map(k=>`<option>${k}</option>`).join('')}</select></label>`,async()=>{const ids=[...$('editorBody').querySelectorAll('.scheduleChoice:checked')].map(x=>x.value);if(!ids.length)throw Error('Approve and select at least one creative revision.');await queue('campaign_schedule',{campaignId:id,campaignIds:ids,startDate:$('campaignStart').value,platform:$('campaignPlatform').value});},'Prepare private drafts');}
function campaignMetrics(id){openEditor('Add an actual performance snapshot',`${field('Source, such as the native analytics view','snapshotSource')}${field('Observation window start, browser local time','snapshotStart','','datetime-local')}${field('Observation window end, browser local time','snapshotEnd','','datetime-local')}<div class="field-pair">${[['Views','snapshotViews'],['Profile visits','snapshotProfiles'],['Link clicks','snapshotClicks'],['Trials','snapshotTrials'],['Paid conversions','snapshotPaid']].map(([label,key])=>field(label+', if measured',key,'','number',false)).join('')}</div><p>Omitted metrics remain unknown. A window shorter than 24 hours is labelled early. No platform connection or measured result is implied by a saved draft.</p>`,async()=>{const start=new Date($('snapshotStart').value),end=new Date($('snapshotEnd').value),hours=(end-start)/3600000;if(!Number.isFinite(hours)||hours<=0||end.getTime()>Date.now())throw Error('Use an actual completed observation window.');const value=id=>$(id).value===''?null:Number($(id).value);for(const key of ['snapshotViews','snapshotProfiles','snapshotClicks','snapshotTrials','snapshotPaid'])if(value(key)!==null&&(!Number.isInteger(value(key))||value(key)<0))throw Error('Use measured nonnegative integer counts or omit unknown values.');await mutate('growthCampaigns/'+id,c=>{c.metricsSnapshots=[...(c.metricsSnapshots||[]),{source:$('snapshotSource').value.trim(),start:start.toISOString(),end:end.toISOString(),hours,views:value('snapshotViews'),profileVisits:value('snapshotProfiles'),clicks:value('snapshotClicks'),trials:value('snapshotTrials'),paidConversions:value('snapshotPaid'),recordedAt:now()}];return c;});});}
function downloadCampaignSlide(id,index){const a=campaigns.find(c=>c.id===id).assets[index],link=document.createElement('a');link.href=a.pngDataUrl;link.download=productId+'-'+a.slideId+'-r'+a.revision+'.png';link.click();notice('Rendered PNG downloaded through your browser.');}

function renderCampaignConversation(selected){const history=forProduct(runs).filter(r=>r.tasks.some(t=>t.id==='organic-campaign-operator')).slice(0,5).reverse();return `<div class="section"><h2>Campaign operator</h2><p class="meta">Context: ${esc(product().name)}${selected?', '+esc(selected.title):''}. Your saved product brief, references and feedback carry forward.</p>${history.map(r=>`<details class="operator-message" ${r.status==='running'?'open':''}><summary>${esc(r.job.split('\nSelected campaign:')[0].slice(0,150))}, ${esc(r.status)}</summary><p><strong>Your request</strong><br>${esc(r.job.split('\nSelected campaign:')[0])}</p>${r.tasks[0].output?`<p><strong>Operator</strong></p><div class="report">${esc(r.tasks[0].output.body)}</div>`:'<p class="meta">The request is in progress. Completed work appears here.</p>'}</details>`).join('')}<form id="campaignChat"><label>What should the operator do?<select id="campaignChatMode"><option value="new">Draft a new concept and slides</option><option value="hook" ${!selected?'disabled':''}>Revise only the selected hook</option><option value="review" ${!selected?'disabled':''}>Review selected campaign results</option></select></label><label>Your message<textarea id="operatorMessage" required maxlength="6000" rows="3"></textarea></label><button class="primary" type="submit">Send to operator</button></form></div>`;}
$('view').onsubmit=async e=>{if(e.target.id!=='campaignChat')return;e.preventDefault();const request=$('operatorMessage').value.trim(),mode=$('campaignChatMode').value,button=e.target.querySelector('button');button.disabled=true;try{if(!request)throw Error('Write your request.');const id=uid();await put('growthCommands/'+id,{id,action:'campaign_request',productId,mode,campaignId:selectedCampaignId||null,request,status:'queued',createdAt:now()});$('operatorMessage').value='';notice('Sent to your campaign operator. The response and produced slides will appear here.');render();}catch(e){error(e);}finally{button.disabled=false;}};

function renderVideoPlan(plan,runId){return `<div class="section"><h3>Filming package</h3><p>Script and estimated timing only. Real footage, caption alignment, rights check and final media review are required.</p><button data-video-plan="${esc(runId)}">Download filming plan JSON</button>${plan.map(v=>`<article><h3>${esc(v.title)}</h3><p>${esc(v.evidenceBasis)}</p><p class="meta">Test: ${esc(v.testVariable)}</p>${v.hooks.map((h,i)=>`<p>Hook ${i+1}${i===v.selectedHook?', selected':''}: ${esc(h)}</p>`).join('')}<pre>${esc(v.scenes.map(x=>`${x.startSec} to ${x.endSec} seconds\nSpoken: ${x.spoken}\nOn screen: ${x.onScreen}\nShot: ${x.shot}`).join('\n\n'))}</pre><p>${esc(v.assetChecklist)}</p></article>`).join('')}</div>`;}

function renderMarketingTeam(){const team=config.marketingTeam;if(!team){$('view').innerHTML='<p>Marketing roster has not loaded.</p>';return;}const core=new Set(team.departments.flatMap(d=>d.roles.map(r=>r.agentId)));$('view').innerHTML=`<p class="lead">Ten departments. Fifty core roles. One product workspace.</p><p>The supplied team diagram is mapped to your existing harness. Eleven matching specialists are reused; ${agents().length-core.size} additional orchestration, production, paid media and launch roles remain available. Each role below opens its instructions, inputs and downstream connections.</p><div class="actions"><button data-workflow="marketing-plan">Ask the orchestrator for a marketing plan</button><button data-action="exportConfig">Download complete agent catalog</button></div><p>Department runs load five specialists, not the entire roster. Missing evidence stays visible. Accounts, live research feeds and final assets are still required for execution. Email agents create draft text only; Amit must approve every exact message before sending.</p>${renderMarketingPriorities()}${team.departments.map(d=>`<section class="section"><div class="row wrap"><div><p class="meta">Department ${esc(d.id)}</p><h2>${esc(d.name)}</h2></div><button data-workflow="${esc(d.workflow)}">Run ${esc(d.name)}</button></div><div class="team-roles">${d.roles.map(r=>{const a=agent(r.agentId),latest=forProduct(runs).flatMap(x=>x.tasks||[]).find(t=>t.id===r.agentId);return `<article><button data-team-agent="${esc(r.agentId)}">${esc(r.name)}</button><p class="meta">${esc(a.name)}, v${a.version}<br>${esc(a.id)}</p><p class="meta">Receives: ${esc(a.dependsOn.map(id=>agent(id)?.name||id).join(', ')||'Product brief and operator job')}</p><p class="meta">Latest task: ${esc(latest?.status||'Not run')}</p></article>`;}).join('')}</div></section>`).join('')}<section class="section"><h2>Existing production and delivery extensions</h2><div class="actions">${agents().filter(a=>!core.has(a.id)).map(a=>`<button data-team-agent="${esc(a.id)}">${esc(a.name)}</button>`).join('')}</div><p>No live accounts or transports are created by adding an agent role. View Account setup, Meta ads, Campaign desk and Content studio for their actual status.</p></section>`;}

function renderMarketingPriorities(){const r=forProduct(runs).find(r=>r.status==='completed'&&r.marketingPlan?.length);return r?`<section class="section"><h2>Orchestrator priorities</h2><p class="meta">Proposals from ${date(r.completedAt)}. No department is dispatched automatically.</p>${r.marketingPlan.map(p=>`<article class="list-row"><h3>${esc(config.marketingTeam.departments.find(d=>d.id===p.departmentId)?.name||p.departmentId)}</h3><p>${esc(p.goal)}</p><p class="meta">Roles: ${p.agentIds.map(esc).join(', ')}<br>Evidence needed: ${p.evidenceNeeded.map(esc).join('; ')||'No additional evidence specified; review before execution.'}</p><button data-workflow="${esc(p.nextWorkflow)}">Review department job</button></article>`).join('')}</section>`:'';}

function renderHarnessFrameworks(){return (config.harnessFrameworks||[]).map(f=>`<section class="section"><h2>${esc(f.title)}</h2><p class="meta">${esc(f.classification)}, ingested ${esc(f.ingestedDate)}</p><a href="${safeURL(f.sourceUrl)}" target="_blank" rel="noopener">Read reference</a>${f.principles.map(p=>`<article class="list-row"><h3>${esc(p.name)}</h3><p>${esc(p.summary)}</p><p><strong>Implemented:</strong> ${esc(p.implemented)}</p><p><strong>Remaining gap:</strong> ${esc(p.gap)}</p></article>`).join('')}<p class="meta">Review stages: ${f.reviewStages.map(esc).join(' → ')}</p></section>`).join('');}
